// @ts-check
/**
 * Sidebar items generator for the main docs plugin.
 *
 * sidebars.js describes four sidebars (cdi, signals, reference, platform) by
 * picking directories and files out of docs/ with the `pick()` helper. Each
 * pick is an `autogenerated` item for the picked path's parent directory,
 * with instructions in `customProps.pick`. This generator runs the default
 * Docusaurus generator on that parent, keeps only the picked item, and then:
 *
 * - removes the previous-versions trees (LEGACY_DIRS), unless the pick asks
 *   for one of them, so old versions only appear under Reference > Legacy
 * - optionally hoists a category's children up one level (`hoist`), putting
 *   the category's index page first
 * - applies label, className, and collapsed overrides
 * - swaps `type: link` docs for link items, and copies index-page
 *   descriptions onto categories so DocCardList can show them
 *
 * No files move, so every /docs/... URL stays the same.
 */

const path = require('path')

/**
 * Directories that hold documentation for old versions of a component. They
 * are listed under Reference > Legacy and removed from every other pick.
 * Keep in sync with the `sidebar_custom_props.outdated` index pages.
 */
const LEGACY_DIRS = [
  'sources/web-trackers/previous-versions',
  'sources/mobile-trackers/previous-versions',
  'sources/react-native-tracker/previous-version',
  'sources/google-tag-manager/previous-versions',
  'sources/node-js-tracker/previous-versions',
  'sources/java-tracker/previous-versions',
  'sources/python-tracker/previous_versions',
  'sources/scala-tracker/previous-versions',
  'api-reference/loaders-storage-targets/bigquery-loader/previous-versions',
  'api-reference/loaders-storage-targets/snowplow-rdb-loader/previous-versions',
  'api-reference/loaders-storage-targets/snowplow-rdb-loader/rdb-loader-configuration-reference/rdb-loader-previous-versions',
  'api-reference/snowplow-mini/previous-releases',
]

const isUnder = (p, dir) => p === dir || p.startsWith(dir + '/')

/**
 * Path of a doc relative to the docs root, without extension. Index pages
 * resolve to their directory: `sources/web-trackers/index.md` becomes
 * `sources/web-trackers`.
 * @param {{ source: string }} doc
 */
function docPath(doc) {
  const rel = doc.source.replace(/^@site\/docs\//, '')
  const noExt = rel.replace(/\.mdx?$/, '')
  return path.posix.basename(noExt) === 'index'
    ? path.posix.dirname(noExt)
    : noExt
}

/** Longest common directory of a list of paths */
function commonDir(paths) {
  if (paths.length === 0) return undefined
  if (paths.length === 1) return paths[0]
  const split = paths.map((p) => p.split('/'))
  const out = []
  for (let i = 0; i < split[0].length; i++) {
    const seg = split[0][i]
    if (split.every((s) => s[i] === seg)) out.push(seg)
    else break
  }
  return out.join('/')
}

/** Every doc id under a generated item, including category links */
function docIdsOf(item) {
  if (item.type === 'doc') return [item.id]
  if (item.type === 'category') {
    const own = item.link?.type === 'doc' ? [item.link.id] : []
    return [...own, ...item.items.flatMap(docIdsOf)]
  }
  return []
}

/** The docs path that a generated item stands for */
function itemPath(item, docsById) {
  if (item.type === 'doc') return docPath(docsById[item.id])
  if (item.type === 'category' && item.link?.type === 'doc') {
    return docPath(docsById[item.link.id])
  }
  const paths = docIdsOf(item).map((id) => docPath(docsById[id]))
  return commonDir(paths)
}

/** Remove previous-versions trees from a list of generated items */
function withoutLegacy(items, docsById, keep) {
  return items.flatMap((item) => {
    const p = itemPath(item, docsById)
    if (p && LEGACY_DIRS.some((dir) => isUnder(p, dir) && !isUnder(keep, dir))) {
      return []
    }
    if (item.type === 'category') {
      return [{ ...item, items: withoutLegacy(item.items, docsById, keep) }]
    }
    return [item]
  })
}

/**
 * Turn doc items with `type: link` front matter into link items, add
 * index-page descriptions to categories, and turn empty categories into docs.
 */
function swap(allItems, linkItems, descriptions) {
  return allItems.flatMap((item) => {
    const className =
      [
        item.className,
        item.customProps?.hidden ? 'hidden' : '',
        item.customProps?.space_above ? 'space-above' : '',
      ]
        .filter(Boolean)
        .join(' ') || undefined

    if (item.type === 'category') {
      // Category pages don't pick up the description in index.md
      // https://docusaurus.io/feature-requests/p/allow-customizing-category-description-in-generated-index-cards
      const customProps = descriptions[item.link?.id]
        ? { ...item.customProps, description: descriptions[item.link.id] }
        : item.customProps

      if (item.items.length > 0)
        return [
          {
            ...item,
            className,
            customProps,
            items: swap(item.items, linkItems, descriptions),
          },
        ]
      // Empty categories don't respect className, so render them as docs
      return [
        {
          type: 'doc',
          id: item.link.id,
          label: item.label,
          className,
          customProps,
        },
      ]
    }

    if (item.type === 'doc' && linkItems[item.id]) {
      return [
        {
          type: 'link',
          label: linkItems[item.id].sidebar_label ?? linkItems[item.id].title,
          href: linkItems[item.id].href,
          className,
          customProps: linkItems[item.id].sidebar_custom_props,
        },
      ]
    }

    return [{ ...item, className }]
  })
}

function linkItemsAndDescriptions(docs) {
  const linkItems = {}
  const descriptions = {}
  for (const doc of docs) {
    if (doc.frontMatter.description) {
      descriptions[doc.id] = doc.frontMatter.description
    }
    if (doc.frontMatter.type === 'link') {
      // Mutate the front matter so useDoc() picks up noindex at render time
      doc.frontMatter.sidebar_custom_props = {
        ...(doc.frontMatter.sidebar_custom_props || {}),
        noindex: true,
      }
      linkItems[doc.id] = { ...doc.frontMatter }
    }
  }
  return { linkItems, descriptions }
}

/** @type {import('@docusaurus/plugin-content-docs').SidebarItemsGeneratorOption} */
async function sidebarItemsGenerator(args) {
  const { defaultSidebarItemsGenerator, item, docs } = args
  const docsById = Object.fromEntries(docs.map((d) => [d.id, d]))
  const { linkItems, descriptions } = linkItemsAndDescriptions(docs)

  /** @type {any} */
  const pickOpts = item.customProps?.pick
  const generated = await defaultSidebarItemsGenerator(args)

  // A plain autogenerated item: generate the directory, minus legacy trees
  if (!pickOpts) {
    return swap(
      withoutLegacy(generated, docsById, item.dirName),
      linkItems,
      descriptions
    )
  }

  const target = pickOpts.path
  const found = generated.find((g) => itemPath(g, docsById) === target)
  if (!found) {
    throw new Error(
      `sidebars.js: pick('${target}') matched nothing in docs/${item.dirName}`
    )
  }

  let picked = withoutLegacy([found], docsById, target)
  if (pickOpts.indexOnly && picked[0]?.type === 'category') {
    const { link, customProps, className } = picked[0]
    picked = [{ type: 'doc', id: link.id, customProps, className }]
  }
  picked = picked.map((p) => ({
    ...p,
    ...(pickOpts.label ? { label: pickOpts.label } : {}),
    ...(pickOpts.className
      ? { className: [p.className, pickOpts.className].filter(Boolean).join(' ') }
      : {}),
    ...(pickOpts.collapsed !== undefined ? { collapsed: pickOpts.collapsed } : {}),
    ...(pickOpts.customProps
      ? { customProps: { ...p.customProps, ...pickOpts.customProps } }
      : {}),
  }))

  if (pickOpts.hoist && picked[0]?.type === 'category') {
    const category = picked[0]
    const index =
      category.link?.type === 'doc'
        ? [
            {
              type: 'doc',
              id: category.link.id,
              label: pickOpts.indexLabel ?? category.label,
            },
          ]
        : []
    picked = [...index, ...category.items]
  }

  return swap(picked, linkItems, descriptions)
}

module.exports = { sidebarItemsGenerator, LEGACY_DIRS, docPath }
